const w = $('Conferir workflow A').first().json;
const e = $input.first().json;
if (w.id !== 'zzWwjKSIrmaL5qXD' || String(e.workflowId) !== w.id || String(e.id) !== '16041') throw new Error('Identidade da execucao nao corresponde ao teste autorizado.');
const runs = e.data?.resultData?.runData ?? {};
const last = runs['Resumo seguro do teste A'];
const s = last?.[last.length - 1]?.data?.main?.[0]?.[0]?.json;
const report = {execucao:String(e.id),workflowId:w.id,statusExecucao:e.status ?? null,inicio:e.startedAt ?? null,fim:e.stoppedAt ?? null,statusHttp:s?.statusCode ?? null,mensagemErro:s?.mensagemErro ?? null,contentType:s?.contentType ?? null,retryAfter:s?.retryAfter ?? null,sucessoHttp:s?.sucessoHttp ?? null,resumoDisponivel:!!s};
if (!s) report.observacao = 'Resumo ausente. Ultimo node: ' + String(e.data?.resultData?.lastNodeExecuted ?? 'nao informado');
const content = '## Resultado real do teste A

' + JSON.stringify(report, null, 2) + '

Somente dados do diagnostico. Nenhuma chave ou nota fiscal incluida. Uma chamada ao SIEG, sem repeticao.';
const nodes = w.nodes.filter(n => n.name !== 'RESULTADO REAL - TESTE A');
nodes.push({id:'7aa5132b-7487-4c49-a4f0-69817d80d6dc',name:'RESULTADO REAL - TESTE A',type:'n8n-nodes-base.stickyNote',typeVersion:1,position:[0,260],parameters:{content,width:720,height:520,color:5}});
return [{json:{workflow:{name:w.name,nodes,connections:w.connections,settings:w.settings ?? {executionOrder:'v1'}}}}];
